package io.knowledgebrain.notification;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_NOTIFICATION_DATABASE_URL",matches=".+")
class GroupReviewStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;GroupReviewStore store;GroupReviewStore.Access a;String schema;Instant now=Instant.parse("2026-10-25T10:00:00Z");
 @BeforeEach void setup(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_URL"));ds.setUser("brain_notification");ds.setPassword(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_PASSWORD"));schema="group_review_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new GroupReviewStore(ds,Clock.fixed(now,ZoneOffset.UTC));a=new GroupReviewStore.Access(ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),1);}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 ReviewSignal.Signal signal(){return ReviewFixtures.signal(a,now.toEpochMilli()+1000);}
 GroupReviewStore.Notice create(){assertTrue(store.accept(signal()));return store.list(a,"ACTIVE","ALL",null,100).items().getLast();}
 void enable(){store.preference(a,store.preference(a).version(),true,ReviewFixtures.trace);}
 void status(int code,Runnable f){assertEquals(code,assertThrows(ResponseStatusException.class,f::run).getStatusCode().value());}
 @Test void defaultOffAndNoOpNeverCreatePreferenceOrInbox(){assertFalse(store.preference(a).enabled());assertEquals(0,store.preference(a).version());store.preference(a,0,false,ReviewFixtures.trace);assertFalse(store.accept(signal()));assertEquals(0,count("group_review_preference"));assertEquals(0,count("group_review_notification"));assertEquals(1,count("group_review_receipt"));assertEquals(0,count("outbox_event"));}
 @Test void enableIsNotRetroactiveAndSuppressedReplayRemainsSuppressed(){var s=signal();assertFalse(store.accept(s));enable();assertFalse(store.accept(s));var old=ReviewFixtures.signal(a,now.toEpochMilli());assertFalse(store.accept(old));assertTrue(store.accept(signal()));assertEquals(3,count("group_review_receipt"));assertEquals(1,count("group_review_notification"));assertEquals(2,count("outbox_event"));}
 @Test void disabledAndSelfChangesAreDurablySkipped(){enable();var s=signal();assertFalse(store.accept(ReviewFixtures.copy(s,s.eventId(),s.payloadHash(),1,a.principalId(),s.occurredAt())));store.preference(a,1,false,ReviewFixtures.trace);var off=signal();assertFalse(store.accept(off));store.preference(a,2,true,ReviewFixtures.trace);assertFalse(store.accept(off));assertEquals(0,count("group_review_notification"));assertEquals(3,store.preferenceHistory(a,Long.MAX_VALUE,10).size());status(412,()->store.preference(a,1,false,ReviewFixtures.trace));}
 @Test void duplicateAndCanonicalReplayPreserveReadStateAndOriginalProvenance(){enable();var s=signal();assertTrue(store.accept(s));var n=store.list(a,"ACTIVE","ALL",null,20).items().getFirst();var changed=store.change(a,n.notificationId(),1,true,false,ReviewFixtures.trace);assertFalse(store.accept(s));assertEquals(changed,store.get(a,n.notificationId()));assertThrows(IllegalArgumentException.class,()->store.accept(ReviewFixtures.copy(s,s.eventId(),"b".repeat(64),1,s.actorId(),s.occurredAt())));assertThrows(IllegalArgumentException.class,()->store.accept(ReviewFixtures.copy(s,ReviewFixtures.ids.next(),s.payloadHash(),1,s.actorId(),s.occurredAt())));assertEquals(1,count("group_review_receipt"));assertEquals(2,count("group_review_revision"));assertEquals(3,count("outbox_event"));}
 @Test void concurrentDuplicateDeliveryHasOneWinner()throws Exception{enable();var s=signal();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var x=pool.submit(()->{barrier.await();return store.accept(s);});var y=pool.submit(()->{barrier.await();return store.accept(s);});assertNotEquals(x.get(),y.get());}assertEquals(1,count("group_review_notification"));assertEquals(1,count("group_review_receipt"));}
 @Test void outboxFailureRollsBackPreferenceAndFirstDeliveryAndReadChange(){sql.execute("CREATE FUNCTION fail_review() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled rollback'; END $$");sql.execute("CREATE TRIGGER fail_review BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_review()");assertThrows(RuntimeException.class,()->enable());assertEquals(0,count("group_review_preference"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_review");enable();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_review");var s=signal();assertThrows(RuntimeException.class,()->store.accept(s));assertEquals(0,count("group_review_receipt"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_review");assertTrue(store.accept(s));var n=store.list(a,"ACTIVE","ALL",null,20).items().getFirst();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_review");assertThrows(RuntimeException.class,()->store.change(a,n.notificationId(),1,true,false,ReviewFixtures.trace));assertEquals(n,store.get(a,n.notificationId()));assertEquals(1,count("group_review_revision"));}
 @Test void membershipEpochChangesRequireNewConsentAndHideOldInbox(){enable();var n=create();var next=new GroupReviewStore.Access(a.groupId(),a.spaceId(),a.principalId(),2);assertFalse(store.preference(next).enabled());assertEquals(1,store.preference(next).version());assertTrue(store.list(next,"ACTIVE","ALL",null,20).items().isEmpty());status(404,()->store.get(next,n.notificationId()));store.preference(next,1,true,ReviewFixtures.trace);assertTrue(store.accept(signal()));assertEquals(1,store.list(next,"ACTIVE","ALL",null,20).items().size());assertEquals(2,store.preference(next).membershipVersion());}
 @Test void catalogCursorIsBoundToRecipientGroupSpaceEpochAndFilters(){enable();for(int i=0;i<22;i++)create();var first=store.list(a,"ACTIVE","UNREAD",null,20);assertEquals(20,first.items().size());assertEquals(2,store.list(a,"ACTIVE","UNREAD",first.nextAfter(),20).items().size());status(400,()->store.list(a,"ACTIVE","ALL",first.nextAfter(),20));status(400,()->store.list(a,"RETIRED","UNREAD",first.nextAfter(),20));status(400,()->store.list(new GroupReviewStore.Access(a.groupId(),a.spaceId(),ReviewFixtures.ids.next(),1),"ACTIVE","UNREAD",first.nextAfter(),20));var n=first.items().getFirst();status(404,()->store.get(new GroupReviewStore.Access(a.groupId(),a.spaceId(),ReviewFixtures.ids.next(),1),n.notificationId()));status(404,()->store.get(new GroupReviewStore.Access(ReviewFixtures.ids.next(),a.spaceId(),a.principalId(),1),n.notificationId()));}
 @Test void readArchiveHistoryAndCasRemainIndependentOfSource(){enable();var n=create();for(int i=1;i<=6;i++)n=store.change(a,n.notificationId(),i,i%2==1,false,ReviewFixtures.trace);var id=n.notificationId();assertEquals(n,store.change(a,id,7,false,false,ReviewFixtures.trace));status(412,()->store.change(a,id,1,true,false,ReviewFixtures.trace));assertEquals(List.of(7L,6L,5L,4L,3L),store.history(a,id,Long.MAX_VALUE,5).stream().map(GroupReviewStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(a,id,3,5).stream().map(GroupReviewStore.Revision::version).toList());assertEquals("RETIRED",store.change(a,id,7,null,true,ReviewFixtures.trace).state());assertTrue(store.list(a,"ACTIVE","ALL",null,20).items().isEmpty());assertEquals(1,store.list(a,"RETIRED","ALL",null,20).items().size());assertEquals(8,count("group_review_revision"));}
 @Test void storageAndOutboxContainNoReviewContent(){enable();var raw=ReviewFixtures.feedback(a,now.toEpochMilli()+100);assertTrue(store.accept(ReviewSignal.decode(ReviewSignal.TOPICS.getFirst(),raw)));for(String table:List.of("group_review_notification","group_review_revision","group_review_preference","group_review_preference_revision")){String text=sql.queryForList("SELECT snapshot::text FROM "+table,String.class).toString();for(String secret:List.of("PRIVATE OPINION","score","reason","content","envelope","payloadHash"))assertFalse(text.contains(secret),secret);}for(byte[] bytes:sql.queryForList("SELECT payload FROM outbox_event",byte[].class))assertFalse(new String(bytes,java.nio.charset.StandardCharsets.UTF_8).contains("PRIVATE OPINION"));assertFalse(store.seeded());store.seededNow();assertTrue(store.seeded());}
}
